  const SK_THRESH=[0,12,30,56,90,132,182,240,306,380], TOOL_THRESH=[0,16,40,74,116,166,226,296,376,466], HERB_DAY_MS=18000, SEASON_DAYS=10;
  const plants=()=>C.content.herbPlants||[], zones=()=>C.content.herbZones||[], seasons=()=>C.content.farmSeasons||[], skills=()=>C.content.herbalistSkills||[], actions=()=>C.content.herbalistActions||[], techniques=()=>C.content.herbalistTechniques||[], reputationTiers=()=>C.content.herbalistReputationTiers||[], tools=()=>C.content.herbalistTools||[], gearDefs=()=>C.content.herbalistGear||[], specDefs=()=>C.content.herbalistSpecializations||[], marketDefs=()=>C.content.herbalistMarket||[], specimenTraits=()=>C.content.herbalistSpecimenTraits||[], rarePrograms=()=>C.content.herbalistRarePrograms||[], uniqueGardens=()=>C.content.herbalistUniqueGardens||[], masterySeals=()=>C.content.herbalistMasterySeals||[], masterCareers=()=>C.content.herbalistMasterCareers||[];
