  function knowledgeXp(id){return Number(S().herbKnowledge?.[id]||0);}
  function knowledgeLevel(id){const xp=knowledgeXp(id);let l=0;for(let i=0;i<K_THRESH.length;i++)if(xp>=K_THRESH[i])l=i;return l;}
  function gainKnowledge(id,n){const s=S(),before=knowledgeLevel(id);s.herbKnowledge[id]=Number(s.herbKnowledge[id]||0)+Math.max(0,n)+careerEffect('knowledgeGain');const after=knowledgeLevel(id);if(before<2&&after>=2)s.stats.plantsIdentified++;if(before<3&&after>=3)C.log(`📚 ${plant(id)?.name||id} est désormais maîtrisée dans l’herbier.`);}
  function skillLevel(id){const xp=Number(S().herbSkills?.[id]||0);let l=1;for(let i=0;i<SK_THRESH.length;i++)if(xp>=SK_THRESH[i])l=i+1;return Math.min(10,l);}
  function gainSkill(id,n){S().herbSkills[id]=Number(S().herbSkills[id]||0)+Math.max(0,n);}
