  function effectiveTechnique(actionId,p=null){const list=techniquesFor(actionId),preferred=technique(S().preferredTechniques?.[actionId]);if(preferred&&techniqueUnlocked(preferred,p))return preferred;return list.filter(t=>techniqueUnlocked(t,p)).sort((a,b)=>Number(b.minSkill||0)-Number(a.minSkill||0)||Number(b.minKnowledge||0)-Number(a.minKnowledge||0))[0]||list[0]||null;}
  function setPreferredTechnique(actionId,id){const t=technique(id);if(!t||t.actionId!==actionId||S().level<Number(t.minLevel||1)||skillLevel(t.skillId)<Number(t.minSkill||1))return;S().preferredTechniques[actionId]=id;C.log(`${t.icon||'🌿'} Geste préféré : ${t.name}.`);C.save();render();}
  function recordTechnique(t){if(!t)return;S().stats.techniquesUsed++;S().herbTechniqueUse[t.id]=Number(S().herbTechniqueUse[t.id]||0)+1;}

  function meetsGate(x){return S().level>=Number(x?.level||x?.minLevel||1)&&rankOrder()>=Number(x?.minRank||0);}
  function programCompleted(id){return !!S().rarePrograms?.[id]?.completed;}
  function gardenCompleted(id){return !!S().uniqueGardens?.[id]?.completed;}
  function rarePlantUnlocked(p){return !p?.rare||!!S().rareUnlocked?.[p.id]||programCompleted(p?.unlockProgramId);}
  function uniqueGardenEffect(key,plantId=''){let n=0;for(const g of uniqueGardens()){if(!gardenCompleted(g.id))continue;if(g.plantId&&plantId&&g.plantId!==plantId)continue;n+=Number(g.effects?.[key]||0);}return n;}
  function masteredCount(rareOnly=false){return plants().filter(p=>(!rareOnly||p.rare)&&knowledgeLevel(p.id)>=3).length;}
  function specimenChance(p){return clamp((p?.rare?.08:.025)+skillLevel('botany')*.002+gearEffect('specimenChance')+specEffect('specimenChance')+uniqueGardenEffect('specimenChance',p?.id),.01,.22);}
  function tryDiscoverSpecimen(p,z,source='observe'){if(!p||!z||Math.random()>=specimenChance(p))return null;const traits=specimenTraits(),pool=traits.filter(t=>Number(t.rarity||1)<=Math.min(3,1+Math.floor((skillLevel('botany')-1)/3)+(p.rare?1:0))),tr=pool[Math.floor(Math.random()*Math.max(1,pool.length))]||traits[0];if(!tr)return null;const sp={id:uid(),plantId:p.id,zoneId:z.id,traitId:tr.id,traitName:tr.name,icon:tr.icon||'✨',qualityBonus:Number(tr.qualityBonus||0),rare:!!p.rare,source,discoveredAt:now()};S().remarkableSpecimens.unshift(sp);S().remarkableSpecimens=S().remarkableSpecimens.slice(0,60);S().stats.remarkableSpecimens++;C.log(`✨ Spécimen remarquable : ${p.name} — ${tr.name}. Il est documenté dans l’herbier.`);return sp;}
  function programRequirementRows(pg){const r=pg?.requirements||{},rows=[],add=(label,have,need)=>rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});add('Niveau Herboriste',S().level,pg?.minLevel||1);add('Grade',rankOrder(),pg?.minRank||0);add('Réputation',S().reputation,pg?.minReputation||0);if(pg?.requiresProgramId)add('Programme précédent',programCompleted(pg.requiresProgramId)?1:0,1);if(r.masteredPlants)add('Plantes maîtrisées',masteredCount(false),r.masteredPlants);if(r.sustainableGathers)add('Cueillettes durables',S().stats.sustainableGathers,r.sustainableGathers);if(r.stationRecoveries)add('Stations rétablies',S().stats.stationRecoveries,r.stationRecoveries);if(r.remarkableSpecimens)add('Spécimens remarquables',S().stats.remarkableSpecimens,r.remarkableSpecimens);if(r.clientId)add(`Confiance ${clients().find(c=>c.id===r.clientId)?.name||r.clientId}`,trust(r.clientId),r.trust||0);return rows;}
  function completeRareProgram(id){ensure();const pg=rareProgram(id);if(!pg||programCompleted(id)||!programRequirementRows(pg).every(x=>x.ok))return;S().rarePrograms[id]={completed:true,completedAt:now()};S().rareUnlocked[pg.plantId]=true;S().stats.rarePlantsUnlocked=Object.values(S().rareUnlocked).filter(Boolean).length;const r=pg.reward||{};C.gainJobXp(JOB,Number(r.jobXp||0));C.gainVillageXp(Number(r.villageXp||0));S().reputation=clamp(Number(S().reputation||0)+Number(r.reputation||0));C.log(`${pg.icon||'⭐'} Programme validé : ${pg.name}. L’accès à ${plant(pg.plantId)?.name||'la plante rare'} est désormais autorisé.`);C.evaluateAchievements?.(false);C.save();render();}
  function gardenRequirementRows(g){const r=g?.requirements||{},rows=[],add=(label,have,need)=>rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});if(g.requiresProgramId)add('Programme de conservation',programCompleted(g.requiresProgramId)?1:0,1);for(const id of g.requiresGardens||[])add(`Jardin ${uniqueGarden(id)?.name||id}`,gardenCompleted(id)?1:0,1);if(g.plantId&&r.knowledge)add(`Connaissance ${plant(g.plantId)?.name||''}`,knowledgeLevel(g.plantId),r.knowledge);if(g.plantId&&r.rareGardenHarvests)add('Récoltes acclimatées',S().rareGardenHarvests[g.plantId]||0,r.rareGardenHarvests);if(r.remarkableSpecimens)add('Spécimens remarquables',S().stats.remarkableSpecimens,r.remarkableSpecimens);if(r.masteredRarePlants)add('Plantes rares maîtrisées',masteredCount(true),r.masteredRarePlants);return rows;}
  function buildUniqueGarden(id){ensure();const g=uniqueGarden(id);if(!g||gardenCompleted(id)||!gardenRequirementRows(g).every(x=>x.ok))return;const cost=g.cost||{},treasury=Number(cost.treasury||0);if(Number(C.state.treasury||0)<treasury)return alert(`Il faut ${treasury} couronnes.`);for(const [rid,qty] of Object.entries(cost)){if(rid==='treasury')continue;if(C.resource(rid)<Number(qty||0))return alert(`Ressource insuffisante : ${C.content.resources.find(r=>r.id===rid)?.name||rid} ${C.resource(rid)}/${qty}.`);}C.state.treasury-=treasury;for(const [rid,qty] of Object.entries(cost)){if(rid!=='treasury'&&Number(qty||0)>0)C.consumeResource(rid,qty,`Jardin unique — ${g.name}`);}S().uniqueGardens[id]={completed:true,completedAt:now()};S().stats.uniqueGardensCompleted=Object.values(S().uniqueGardens).filter(x=>x?.completed).length;C.gainJobXp(JOB,g.final?150:70);C.gainVillageXp(g.final?35:15);C.log(`${g.icon||'🌿'} Jardin unique achevé : ${g.name}.`);C.evaluateAchievements?.(false);C.save();render();}
  window.herbalistCompleteRareProgram=completeRareProgram;window.herbalistBuildUniqueGarden=buildUniqueGarden;
  function ownsTool(id){return S().ownedTools.includes(id);}function ownsGear(id){return S().ownedGear.includes(id);}
  function toolMax(id){return Number(herbTool(id)?.maxDurability||100);}function toolCondition(id){if(typeof S().toolCondition[id]!=='number')S().toolCondition[id]=toolMax(id);return Number(S().toolCondition[id]||0);}function toolConditionPct(id){return toolMax(id)?toolCondition(id)/toolMax(id)*100:0;}
  function toolMastery(id){const xp=Number(S().toolXp[id]||0);let lvl=1;for(let i=1;i<TOOL_THRESH.length;i++)if(xp>=TOOL_THRESH[i])lvl=i+1;return Math.min(10,lvl);}function equippedTool(operation){const t=herbTool(S().equippedTools[operation]);return t&&ownsTool(t.id)?t:null;}
  function gearEffect(key){let n=0;for(const id of Object.values(S().equippedGear||{})){const g=herbGear(id);if(g&&ownsGear(id))n+=Number(g.effects?.[key]||0);}return n;}
  function activeSpec(id){return S().specialization.primary===id||S().specialization.secondary===id;}function hasTalent(id){return !!S().specialization.talents[id];}function spentInSpec(id){const d=specDef(id);return d?(d.talents||[]).filter(t=>hasTalent(t.id)).reduce((a,t)=>a+Number(t.cost||1),0):0;}function specPointsSpent(){return specDefs().reduce((a,d)=>a+spentInSpec(d.id),0);}function specPointTotal(){return Math.max(0,Math.floor((S().level-3)/2));}function specPointsFree(){return Math.max(0,specPointTotal()-specPointsSpent());}function specEffect(key){let n=0;for(const d of specDefs())if(activeSpec(d.id))for(const t of d.talents||[])if(hasTalent(t.id))n+=Number(t.effects?.[key]||0);return n;}function canInvestTalent(specId,t){return activeSpec(specId)&&!hasTalent(t.id)&&specPointsFree()>=Number(t.cost||1)&&(t.requires||[]).every(hasTalent);}
  function toolScale(operation){const t=equippedTool(operation);if(!t)return .76;const cond=clamp(toolConditionPct(t.id)/100,0,1);if(cond<=0)return .76;return Number(t.efficiency||1)*(.64+.36*cond)*(1+(toolMastery(t.id)-1)*.012);}function toolEffect(operation,key){const t=equippedTool(operation);if(!t)return 0;const cond=clamp(toolConditionPct(t.id)/100,0,1);if(cond<=0)return 0;return Number(t[key]||0)*(.5+.5*cond);}function wearTool(operation,mult=1){const t=equippedTool(operation);if(!t)return;const wear=Number(t.wear||1)*Math.max(.35,Number(mult||1))*Math.max(.45,1+gearEffect('toolWear'));S().toolCondition[t.id]=clamp(toolCondition(t.id)-wear,0,toolMax(t.id));S().toolXp[t.id]=Number(S().toolXp[t.id]||0)+2*Math.max(.5,Number(mult||1));if(S().toolCondition[t.id]<=0)C.log(`🧰 ${t.name} est hors service : entretiens-le pour retrouver ses bonus.`);}function repairCost(id){const t=herbTool(id),missing=Math.max(0,toolMax(id)-toolCondition(id));if(!t||missing<=.5)return 0;if(t.starter&&toolCondition(id)<=0)return 0;return Math.max(1,Math.ceil(Number(t.repairBase||5)*(missing/toolMax(id))*Math.max(.35,1-careerEffect('repairDiscount'))));}
  function conditionLabel(id){const p=toolConditionPct(id);return p>=75?'Excellent':p>=45?'Correct':p>=20?'Usé':p>0?'Très usé':'Hors service';}
  function marketDemand(id){return Number(S().marketDemand[id]??1);}function refreshMarket(force=false){const t=now();if(!force&&t-Number(S().lastMarketTick||0)<180000)return;for(const m of marketDefs()){const lo=Number(m.minDemand||.75),hi=Number(m.maxDemand||1.4),cur=marketDemand(m.id),target=1+(Math.random()-.5)*.34;S().marketDemand[m.id]=clamp(cur*.55+target*.45,lo,hi);}S().lastMarketTick=t;}function demandLabel(v){return v>=1.14?'forte':v<=.90?'faible':'normale';}function demandClass(v){return v>=1.14?'high':v<=.90?'low':'normal';}
  function traceableQty(resourceId){return S().herbLots.filter(l=>l.resourceId===resourceId&&Number(l.quantity||0)>0).reduce((n,l)=>n+Number(l.quantity||0),0);}function looseQty(resourceId){return Math.max(0,C.resource(resourceId)-traceableQty(resourceId));}
  function marketBaseBonus(){return gearEffect('marketBonus')+specEffect('marketBonus')+uniqueGardenEffect('marketBonus')+careerEffect('marketBonus');}function lotMarketBonus(l){let n=marketBaseBonus();if(l.prepared)n+=specEffect('driedMarket');if(l.origin==='garden')n+=specEffect('gardenMarket');if(l.sustainable)n+=specEffect('sustainableMarket');return n;}
  function lotPrice(l){const m=marketItem(l?.resourceId);if(!m)return 0;const q=clamp(Number(l.quality||50),0,100),conf=clamp(Number(l.confidence||50),20,100),quality=.56+q*.009,certainty=.82+conf*.0022,trace=1+(l.sustainable?0.04:0)+(l.origin==='garden'?0.03:0),transport=1+gearEffect('marketTransport');return Math.max(1,Math.round(Number(l.quantity||0)*Number(m.basePrice||1)*marketDemand(m.id)*quality*certainty*trace*transport*(1+lotMarketBonus(l))));}
  function looseUnitPrice(resourceId){const m=marketItem(resourceId);return m?Math.max(.05,Math.round(Number(m.basePrice||1)*marketDemand(resourceId)*.68*(1+gearEffect('marketTransport'))*(1+marketBaseBonus())*100)/100):0;}

  function calendarState(at=now()){const defs=seasons().length?seasons():[{id:'spring',name:'Printemps',icon:'🌱'}];if(!Number.isFinite(Number(C.state.worldCalendarAnchorAt)))C.state.worldCalendarAnchorAt=at;const elapsed=Math.max(0,at-Number(C.state.worldCalendarAnchorAt||at)),totalDays=Math.floor(elapsed/HERB_DAY_MS),seasonIndex=Math.floor(totalDays/SEASON_DAYS)%defs.length,day=totalDays%SEASON_DAYS+1,year=Math.floor(totalDays/(SEASON_DAYS*defs.length))+1;return{year,day,totalDays,season:defs[seasonIndex]||defs[0],seasonIndex,nextAt:Number(C.state.worldCalendarAnchorAt||at)+(totalDays+1)*HERB_DAY_MS};}
  function zoneUnlocked(z){return !!z&&C.built(BUILDING)&&S().level>=Number(z.minLevel||1)&&C.buildingLevel(BUILDING)>=Number(z.minBuildingLevel||1)&&(!z.unique||programCompleted(z.unlockProgramId));}
  function plantUnlocked(p){return !!p&&rarePlantUnlocked(p)&&S().level>=Number(p.minLevel||1)&&knowledgeLevel(p.id)>=Number(p.minKnowledge||0)&&p.zoneIds.some(id=>zoneUnlocked(zone(id)));}
  function stationCapacity(z,p){return Math.max(8,Math.round(Number(z?.capacity||100)*Number(p?.zoneDensity?.[z?.id]??.65)));}
  function seasonYieldFactor(p,seasonId=calendarState().season?.id){return Math.max(0,Number(p?.seasonYield?.[seasonId]??1));}
  function seasonQualityBonus(p,seasonId=calendarState().season?.id){return Number(p?.seasonQuality?.[seasonId]??0);}
  function zoneSeasonRegen(z,seasonId=calendarState().season?.id){return Math.max(.05,Number(z?.seasonalRegen?.[seasonId]??1));}
  function wildSeasonAvailable(p){return seasonYieldFactor(p)>.05&&!p?.dormantSeasons?.includes(calendarState().season?.id);}
  function seasonFitLabel(p){const f=seasonYieldFactor(p);return f>=1.08?'Pleine saison':f>=.78?'Favorable':f>=.32?'Marginale':'Dormance';}
  function stationState(zoneId,plantId){return S().zoneState?.[zoneId]?.plantState?.[plantId]||null;}
  function stationProtected(zoneId,plantId){return Number(stationState(zoneId,plantId)?.protectedUntil||0)>now();}
