      gainKnowledge(p.id,gain);gainSkill('botany',4+Number(t?.skillXpBonus||0));recordTechnique(t);s.stats.observations++;if(Number(t?.precision||0)>=8)s.stats.preciseObservations++;
      wearTool('observe',.7);C.gainJobXp(JOB,4+Math.floor(Number(t?.precision||0)/7));C.gainMastery(JOB,1);C.log(`🔎 ${t?.name||'Observation'} : ${p.name} · connaissance +${gain} · fiabilité ${identificationReliability(p,t)}%.`);if(z)tryDiscoverSpecimen(p,z,'observe');
