      ps.abundance=Math.max(0,Number(ps.abundance||0)-depl);const afterRatio=Number(ps.abundance||0)/capPop,safe=Number(p.safeHarvestRatio||.4),ecologyStress=Math.max(0,safe-afterRatio),healthLoss=Math.max(.4,depl*.20/Math.max(.6,Number(z.resilience||1))*(sustainableGesture?.62:1)+ecologyStress*18);ps.health=clamp(Number(ps.health||100)-healthLoss,0,100);recordTechnique(t);
      const mistake=Math.random()<misidentificationChance(p,t);
      s.stats.gathers++;s.stats.seasonalHarvests++;s.seasonHarvests[calendarState().season?.id]=Number(s.seasonHarvests[calendarState().season?.id]||0)+1;gainSkill('gathering',5+Number(t?.skillXpBonus||0));gainSkill('botany',1);C.gainJobXp(JOB,7);C.gainMastery(JOB,2);C.gainVillageXp(1);
      if(Number(t?.precision||0)>=7)s.stats.preciseGathers++;const sustainable=sustainableGesture&&afterRatio>=safe*.72;if(sustainable)s.stats.sustainableGathers++;
