    const s=S(),lot=s.herbLots.find(x=>x.id===id&&!x.prepared),p=plant(lot?.plantId);if(!lot||!p)return false;
    const qty=Math.floor(Number(lot.quantity||0));if(qty<=0||C.resource(lot.resourceId)<qty)return false;
    const t=taskTechnique||effectiveTechnique('dry',p),prep=skillLevel('preparation'),frag=Number(p.fragility||.5),lossChance=clamp(Math.max(0,Number(t?.lossRisk||0)-toolEffect('dry','lossReduction'))*(.65+frag)*(1-(prep-1)*.04)*Math.max(.35,1-specEffect('dryLossReduction')),0,.35),lost=Math.random()<lossChance?Math.min(qty>2?1:0,qty):0,outQty=qty-lost;
    const q=Math.round(clamp(Math.min(Number(lot.quality||50)-1+(prep-1)*1.25+Number(t?.qualityBonus||0)+toolEffect('dry','qualityBonus')+gearEffect('quality')+specEffect('dryQuality')+careerEffect('dryQuality')-frag*1.5,qualityCap(p)),20,99));
    C.consumeResource(lot.resourceId,qty,`Séchage Herboriste — ${p.name}`);if(outQty>0)C.addResource(p.driedResourceId,outQty,`Séchage Herboriste — ${p.name}`);lot.quantity=0;
    if(outQty>0)addLot({plantId:p.id,resourceId:p.driedResourceId,quantity:outQty,quality:q,zoneId:lot.zoneId,prepared:true,origin:lot.origin,techniqueId:t?.id||'',confidence:lot.confidence||identificationReliability(p,t),sustainable:!!lot.sustainable,seasonId:lot.seasonId||calendarState().season?.id,stationHealth:lot.stationHealth});
    recordTechnique(t);wearTool('dry');gainSkill('preparation',Math.max(3,outQty)+Number(t?.skillXpBonus||0));gainKnowledge(p.id,1);s.stats.dried+=outQty;if(q>=78)s.stats.highQualityUnits+=outQty;if(q>=84)s.stats.expertDryings++;
