  function contractEligible(d){const c=clients().find(x=>x.id===d?.clientId);if(!d||!c)return false;if(d.requiresMaster&&!S().masterCertified)return false;if(c.masterOnly&&!S().masterCertified)return false;if(d.requiredGardenId&&!gardenCompleted(d.requiredGardenId))return false;if(rankOrder()<Number(c.minRank||0)||rankOrder()<Number(d.minRank||0)||S().level<Number(d.minLevel||1)||S().reputation<Number(d.minReputation||0)||trust(d.clientId)<Number(d.minTrust||0))return false;const hc=d.herbCriteria||{},p=plant(hc.plantId);if(p&&!plantUnlocked(p))return false;if(Number(hc.minKnowledge||0)>knowledgeLevel(hc.plantId))return false;if(hc.zoneId&&!zoneUnlocked(zone(hc.zoneId)))return false;if(hc.zoneId&&p){const cached=matchingLots(d).reduce((n,l)=>n+Number(l.quantity||0),0),blocked=!wildSeasonAvailable(p)||stationRatio(hc.zoneId,p.id)<=Number(p.criticalRatio||.14);if(blocked&&cached<Number(d.quantity||1))return false;}return true;}
  function refreshOffers(force=false){const s=S(),t=now();if(!force&&Array.isArray(s.contractOffers)&&s.contractOffers.length&&t-Number(s.lastContractRefresh||0)<90000)return;const pool=contracts().filter(contractEligible).filter(d=>!s.activeContracts.some(x=>x.contractId===d.id));const shuffled=pool.sort(()=>Math.random()-.5);s.contractOffers=shuffled.slice(0,Math.min(5,offerLimit())).map(d=>({contractId:d.id,offeredAt:t}));s.lastContractRefresh=t;}
  function acceptContract(id){ensure();const s=S(),d=contracts().find(x=>x.id===id),c=clients().find(x=>x.id===d?.clientId);if(!d||!s.contractOffers.some(x=>x.contractId===id)||!contractEligible(d))return;const cap=activeContractLimit();if(s.activeContracts.length>=cap)return alert(`Maximum ${cap} contrat(s) actif(s) avec ton grade et ta réputation actuels.`);const grace=1+reputationEffect('deadlineBonus')+clientEffect(c,'deadlineBonus')+gearEffect('deadlineBonus');s.activeContracts.push({id:uid(),contractId:id,acceptedAt:now(),deadline:now()+Number(d.duration||240)*1000*grace});s.contractOffers=s.contractOffers.filter(x=>x.contractId!==id);C.log(`📜 Contrat Herboriste accepté : ${d.name}${grace>1?` · délai relationnel +${Math.round((grace-1)*100)}%`:''}.`);C.save();render();}
  function matchingLots(d){const hc=d.herbCriteria||{};return S().herbLots.filter(l=>l.resourceId===d.resourceId&&Number(l.quantity||0)>0&&Number(l.quality||0)>=Number(hc.qualityMin||0)&&Number(l.confidence||0)>=Number(hc.minConfidence||0)&&(!hc.plantId||l.plantId===hc.plantId)&&(!hc.prepared||l.prepared)&&(!hc.zoneId||l.zoneId===hc.zoneId)&&(!hc.origin||l.origin===hc.origin)&&(!hc.sustainable||!!l.sustainable)).sort((a,b)=>b.quality-a.quality);}
  function deliverContract(activeId){ensure();const s=S(),a=s.activeContracts.find(x=>x.id===activeId),d=contracts().find(x=>x.id===a?.contractId);if(!a||!d)return;const lots=matchingLots(d),need=Number(d.quantity||1),have=lots.reduce((n,l)=>n+Number(l.quantity||0),0);if(have<need)return alert(`Lot compatible insuffisant : ${have}/${need}.`);if(C.resource(d.resourceId)<need)return alert('Le stock partagé ne contient plus la quantité requise.');let left=need,weighted=0;for(const l of lots){const take=Math.min(left,Number(l.quantity||0));l.quantity-=take;left-=take;weighted+=take*Number(l.quality||0);if(left<=0)break;}C.consumeResource(d.resourceId,need,`Contrat Herboriste — ${d.name}`);const avg=weighted/need,remarkableThreshold=Math.min(98,Math.max(82,Number(d.herbCriteria?.qualityMin||0)+10)),remarkable=avg>=remarkableThreshold,r=d.reward||{},c=clients().find(x=>x.id===d.clientId),rewardBonus=careerEffect('contractReward')+clientEffect(c,'contractReward')+gearEffect('contractReward')+specEffect('contractReward'),trustMult=1+careerEffect('trustGain')+clientEffect(c,'trustGain'),treasuryBase=Number(r.treasury||0),treasuryGain=Math.round(treasuryBase*(1+rewardBonus)),trustGain=Math.max(1,Math.round((Number(r.trust||0)+(remarkable?2:0))*trustMult));C.state.treasury=Number(C.state.treasury||0)+treasuryGain;C.gainJobXp(JOB,Number(r.jobXp||0));C.gainVillageXp(Number(r.villageXp||0));s.reputation=clamp(Number(s.reputation||0)+Number(r.reputation||0)+(remarkable?2:0));s.clientTrust[d.clientId]=clamp(trust(d.clientId)+trustGain);s.completedContracts++;if(remarkable)s.stats.remarkableContracts++;if(Number(d.minRank||0)>=4||['rare','master','masterwork','council'].includes(d.category))s.stats.prestigeContracts++;if(d.category==='rare'||d.category==='masterwork')s.stats.rareContracts++;if(d.requiresMaster)s.stats.masterContracts++;C.gainMastery(JOB,remarkable?4:2);s.contractHistory.unshift({t:now(),contractId:d.id,status:'delivered',quality:Math.round(avg),remarkable});s.contractHistory=s.contractHistory.slice(0,60);s.activeContracts=s.activeContracts.filter(x=>x.id!==activeId);C.log(`✅ ${d.name} livré${remarkable?' — lot remarquable':''} · ${treasuryGain} couronnes${rewardBonus?` (+${Math.round(rewardBonus*100)}% relation/renommée)`:''}.`);refreshOffers(true);C.save();render();}
  function expireContracts(){const s=S(),expired=s.activeContracts.filter(a=>Number(a.deadline||0)<=now());for(const a of expired){const d=contracts().find(x=>x.id===a.contractId),f=d?.failure||{};s.reputation=clamp(Number(s.reputation||0)-Number(f.reputation||0));if(d)s.clientTrust[d.clientId]=clamp(trust(d.clientId)-Number(f.trust||0));s.failedContracts++;s.contractHistory.unshift({t:now(),contractId:a.contractId,status:'failed'});C.log(`⌛ Contrat Herboriste échoué : ${d?.name||a.contractId}.`);}if(expired.length){s.activeContracts=s.activeContracts.filter(x=>!expired.includes(x));refreshOffers(true);}}

  function rankRequirements(rank){const r=rank?.requirements||{},rows=[],add=(label,have,need)=>{if(Number(need||0)>0)rows.push({label,have:Number(have||0),need:Number(need||0),ok:Number(have||0)>=Number(need||0)});};add('Niveau métier',S().level,rank?.minLevel||1);add('Niveau village',C.state.level,rank?.minVillageLevel||1);for(const [k,label] of Object.entries({observations:'Observations',gathers:'Cueillettes',stored:'Unités récoltées',dried:'Unités séchées',cultivations:'Cultures lancées',techniquesUsed:'Gestes techniques pratiqués',preciseGathers:'Cueillettes précises',sustainableGathers:'Cueillettes durables'}))add(label,S().stats[k]||0,r[k]);add('Contrats réussis',S().completedContracts,r.contractsCompleted);add('Contrats remarquables',S().stats.remarkableContracts||0,r.remarkableContracts);add(`Commanditaires à confiance ≥ ${Number(r.trustThreshold||25)}`,trustedClientCount(r.trustThreshold||25),r.trustedClients);add('Réputation',S().reputation,r.reputation);add('Botanique',skillLevel('botany'),r.skillBotany);add('Cueillette',skillLevel('gathering'),r.skillGathering);add('Culture',skillLevel('cultivation'),r.skillCultivation);add('Préparation',skillLevel('preparation'),r.skillPreparation);if(Number(r.knowledgeCount||0)>0)add(`Plantes connaissance ≥ ${K_NAMES[Number(r.knowledgeLevel||1)]}`,plants().filter(p=>knowledgeLevel(p.id)>=Number(r.knowledgeLevel||1)).length,r.knowledgeCount);return rows;}
  function promote(){const n=C.nextProfessionalRank(JOB);if(!n||!rankRequirements(n).every(x=>x.ok))return;C.promoteJob(JOB);S().lastContractRefresh=0;C.gainVillageXp(8+Number(n.order||0)*4);C.save();render();}

  window.herbalistBuyTool=id=>{ensure();const t=herbTool(id);if(!t||ownsTool(id)||!meetsGate(t))return;const price=Number(t.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedTools.push(id);S().toolCondition[id]=toolMax(id);S().toolXp[id]=0;if(!S().equippedTools[t.operation])S().equippedTools[t.operation]=id;S().stats.equipmentBought++;C.log(`🧰 Outil Herboriste acheté : ${t.name}.`);C.save();render();};
  window.herbalistEquipTool=id=>{ensure();const t=herbTool(id);if(!t||!ownsTool(id)||!meetsGate(t))return;S().equippedTools[t.operation]=id;C.log(`🧰 ${t.name} équipé pour ${t.operation}.`);C.save();render();};
  window.herbalistRepairTool=id=>{ensure();const t=herbTool(id);if(!t||!ownsTool(id)||toolCondition(id)>=toolMax(id)-.5)return;const cost=repairCost(id);if(cost<=0&&t.starter&&toolCondition(id)<=0){S().toolCondition[id]=Math.round(toolMax(id)*.25);C.log(`🔧 Remise en état de secours : ${t.name} revient à 25 %.`);}else{if(Number(C.state.treasury||0)<cost)return alert(`Il faut ${cost} couronnes.`);C.state.treasury-=cost;S().toolCondition[id]=toolMax(id);S().stats.repairs++;C.log(`🔧 ${t.name} entretenu pour ${cost} couronnes.`);}C.save();render();};
  window.herbalistBuyGear=id=>{ensure();const g=herbGear(id);if(!g||ownsGear(id)||!meetsGate(g))return;const price=Number(g.price||0);if(Number(C.state.treasury||0)<price)return alert(`Il faut ${price} couronnes.`);C.state.treasury-=price;S().ownedGear.push(id);if(!S().equippedGear[g.slot])S().equippedGear[g.slot]=id;S().stats.equipmentBought++;C.log(`🎒 Équipement Herboriste acheté : ${g.name}.`);C.save();render();};
  window.herbalistEquipGear=id=>{ensure();const g=herbGear(id);if(!g||!ownsGear(id)||!meetsGate(g))return;S().equippedGear[g.slot]=id;C.log(`🎒 ${g.name} équipé.`);C.save();render();};
  window.herbalistSellLoose=(id,all=false)=>{ensure();refreshMarket();const qtyAvail=looseQty(id),m=marketItem(id);if(!m||qtyAvail<=0)return;const qty=all?qtyAvail:1,total=Math.round(looseUnitPrice(id)*qty*100)/100;if(!C.consumeResource(id,qty,'Vente botanique non traçable'))return;C.state.treasury=Number(C.state.treasury||0)+total;S().stats.marketSales+=qty;S().stats.looseSales+=qty;S().stats.marketRevenue+=total;S().marketDemand[id]=clamp(marketDemand(id)-qty*.006,Number(m.minDemand||.7),Number(m.maxDemand||1.5));C.log(`💰 Stock botanique courant vendu : ${qty} × ${m.name} pour ${total.toFixed(2)} couronnes.`);C.save();render();};
  window.herbalistSellLot=id=>{ensure();refreshMarket();const l=S().herbLots.find(x=>x.id===id&&Number(x.quantity||0)>0),m=marketItem(l?.resourceId);if(!l||!m)return;const qty=Number(l.quantity||0),total=lotPrice(l);if(C.resource(l.resourceId)<qty)return alert('Le stock partagé ne contient plus ce lot.');if(!C.consumeResource(l.resourceId,qty,'Vente lot botanique traçable'))return;S().herbLots=S().herbLots.filter(x=>x.id!==id);C.state.treasury=Number(C.state.treasury||0)+total;S().stats.marketSales+=qty;S().stats.traceableSales+=qty;S().stats.marketRevenue+=total;S().marketDemand[l.resourceId]=clamp(marketDemand(l.resourceId)-qty*.008,Number(m.minDemand||.7),Number(m.maxDemand||1.5));C.log(`💰 Lot botanique vendu : ${qty} ${m.name.toLowerCase()}, Q${Math.round(l.quality||0)}, pour ${total} couronnes.`);C.save();render();};
  window.herbalistChooseSpec=id=>{ensure();const d=specDef(id);if(!d||S().level<Number(d.minLevel||5)||rankOrder()<Number(d.minRank||2))return;if(!S().specialization.primary){S().specialization.primary=id;C.log(`🧭 Spécialisation principale Herboriste : ${d.name}.`);}else if(S().specialization.primary!==id&&!S().specialization.secondary&&rankOrder()>=5&&spentInSpec(S().specialization.primary)>=4){S().specialization.secondary=id;C.log(`🧭 Spécialisation secondaire Herboriste : ${d.name}.`);}C.save();render();};
